const fastArmNow = Clock.currentTimeMillis.pipe(
  Effect.flatMap((now) =>
    storageOperation("wake maintenance lanes", async () => {
      const next = DueQueue.next(DueQueue.make(ctx.storage).read());

      if (!Number.isFinite(next)) return;
      const existing = await ctx.storage.getAlarm();

      // A pending due alarm already owns this droppable promptness hint.
      if (existing !== null && existing <= Math.max(now, next)) return;

      await ctx.storage.transaction(async (transaction) => {
        const next = DueQueue.next(DueQueue.make(ctx.storage).read());

        if (Number.isFinite(next))
          await ensureTransactionAlarmBy(transaction, Math.max(now, next));
      });
    }),
  ),
);
